/// The declarations of one tool, by the name `gatk <Tool>` resolves.
pub fn declarations(tool: &str) -> Option<&'static [Declaration]> {
    match tool {
        "CountReads" => Some(COUNTREADS),
        "CountVariants" => Some(COUNTVARIANTS),
        "PrintReads" => Some(PRINTREADS),
        _ => None,
    }
}
